mapper.select:
SELECT
FROM scm_print_template WHERE deleted = FALSE
AND document_type = #{query.documentType}
AND (template_code ILIKE CONCAT('%', #{query.keyword}, '%') OR template_name ILIKE CONCAT('%', #{query.keyword}, '%'))
AND enabled_flag = #{query.enabledFlag}
ORDER BY document_type ASC, default_flag DESC, template_code ASC, id ASC

SELECT

FROM scm_print_template
WHERE document_type = #{documentType}
  AND template_code = #{templateCode}
  AND deleted = FALSE

mapper.update:
UPDATE scm_print_template
SET default_flag = FALSE,
    version      = version + 1,
    updated_at   = CURRENT_TIMESTAMP,
    updated_by   = #{operator}
WHERE document_type = #{documentType}
  AND deleted = FALSE
  AND default_flag = TRUE

    AND id <> #{keepId}

UPDATE scm_print_template
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND deleted = FALSE
  AND version = #{version}
